NODE_PATH=/tmp/sqlite/node_modules node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for booking BK-B70889 in likely tables
const tables = ['flight_bookings', 'hotel_reservations', 'car_rentals'];
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t + ')').all().map(c => c.name);
  console.log(t + ' columns:', cols.join(', '));
  // Search all text columns for the booking ID
  const rows = db.prepare('SELECT * FROM ' + t).all();
  const matches = rows.filter(r => JSON.stringify(r).includes('BK-B70889'));
  if (matches.length > 0) {
    console.log('FOUND in ' + t + ':');
    console.log(JSON.stringify(matches, null, 2));
  }
}
db.close();
"

